class Solution:
    def compactShelf(self, slots: List[int]) -> List[int]:
        a, changed = slots[:], True
        while changed:
            changed = False
            for i in range(len(a) - 1):
                if a[i] == 0 and a[i + 1] != 0:
                    a[i], a[i + 1] = a[i + 1], a[i]
                    changed = True
        return a

