class Solution {
    public int[] compactShelf(int[] slots) {
        int[] a = slots.clone();
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i + 1 < a.length; i++)
                if (a[i] == 0 && a[i + 1] != 0) { a[i] = a[i + 1]; a[i + 1] = 0; changed = true; }
        }
        return a;
    }
}

