        bool changed = true;
        while (changed) {
            changed = false;
            for (size_t i = 0; i + 1 < a.size(); i++)
                if (a[i] == 0 && a[i + 1] != 0) { swap(a[i], a[i + 1]); changed = true; }
        }
        return a;
    }
};

