int* compactShelf(int* slots, int slotsSize, int* returnSize) {
    int* a = malloc(slotsSize * sizeof(int));
    memcpy(a, slots, slotsSize * sizeof(int));
    int changed = 1;
    while (changed) {
        changed = 0;
        for (int i = 0; i + 1 < slotsSize; i++)
            if (a[i] == 0 && a[i + 1] != 0) { a[i] = a[i + 1]; a[i + 1] = 0; changed = 1; }
    }
    *returnSize = slotsSize;
    return a;
}

