class Solution:
    def compactShelf(self, slots: List[int]) -> List[int]:
        a, write = slots[:], 0
        for x in slots:
            if x != 0:
                a[write] = x
                write += 1
        for i in range(write, len(a)):
            a[i] = 0
        return a

