class Solution {
    public int[] compactShelf(int[] slots) {
        int[] a = slots.clone();
        int write = 0;
        for (int x : slots) if (x != 0) a[write++] = x;
        for (int i = write; i < a.length; i++) a[i] = 0;
        return a;
    }
}

